import random

# Your display string indices
disp_str = "38394041505152535455"
# Parse them into a list of 2-digit strings, then format to 4 digits
disp_indices = [f"{int(disp_str[i:i+2]):04d}" for i in range(0, len(disp_str), 2)]

# Your exact string tag indices block (concatenated)
tag_str = (
    ""
    ""
)

# Parse the continuous string tag numbers
tag_indices = []
current_val = 1
i = 0
while i < len(tag_str):
    for length in [1, 2, 3, 4]: # Numbers incrementally grow from 1 to 1237
        if i + length <= len(tag_str):
            val = int(tag_str[i:i+length])
            if val >= current_val:
                tag_indices.append(val)
                current_val = val + 1
                i += length
                break

# Generate and save the commands
with open(r"C:\Users\amb3942\Desktop\Untitled spreadsheet - Sheet1.csv", "w") as f:
    for tag in tag_indices:
        random_disp = random.choice(disp_indices)
        formatted_tag = f"{tag:04d}"
        command = f"STR_TEST:FIX:{random_disp}:{formatted_tag}"
        f.write(command + "\n")
        print(command) # Optional: prints to console as it builds

print("\nFinished generating commands in 'commands.txt'")